397→// run executes a subcommand on the external binary and returns stdout bytes.
398→// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
399→// included in the returned error.
400→func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
401→	// Apply a default timeout when the caller hasn't set a deadline, so a hung
402→	// external binary can't block the CLI (or git hooks) indefinitely.
403→	if _, ok := ctx.Deadline(); !ok {
404→		var cancel context.CancelFunc
405→		ctx, cancel = context.WithTimeout(ctx, defaultRunTimeout)
406→		defer cancel()
407→	}
408→	cmd := exec.CommandContext(ctx, e.binaryPath, args...)
409→	// Ensure I/O goroutines are released shortly after the process is killed,
410→	// so cmd.Run() doesn't block waiting for pipe reads.
411→	cmd.WaitDelay = 3 * time.Second
412→
413→	// Set environment: repo root + protocol version
414→	cmd.Env = append(cmd.Environ(),
415→		"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
416→	)
417→	if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
418→		cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
419→		cmd.Dir = repoRoot
420→	}
421→
422→	if stdin != nil {
423→		cmd.Stdin = bytes.NewReader(stdin)
424→	}
425→
426→	var stdoutBuf, stderrBuf bytes.Buffer
427→	cmd.Stdout = &stdoutBuf
428→	cmd.Stderr = &stderrBuf
429→
430→	if err := cmd.Run(); err != nil {
431→		errMsg := strings.TrimSpace(stderrBuf.String())
432→		if errMsg != "" {
433→			return nil, fmt.Errorf("%s: %s", args[0], errMsg)
434→		}
435→		return nil, fmt.Errorf("%s: %w", args[0], err)
436→	}
437→
438→	return stdoutBuf.Bytes(), nil
439→}
